def smallest_missing(A, left_element, right_element):
    """Find the smallest missing element in a sorted array.

    Looks for the smallest integer ``x`` with
    ``left_element <= x <= right_element`` that is not present in ``A``.
    If every integer in that interval is present, returns
    ``right_element + 1``.

    ``left_element``/``right_element`` therefore work both as a value
    interval and, for arrays of distinct non-negative ints starting at 0,
    as ``[left, right]`` index bounds, since the two interpretations
    coincide in that case.
    """
    present = set(A) if A is not None else set()
    for x in range(left_element, right_element + 1):
        if x not in present:
            return x
    return right_element + 1
